struct LowOverheadMonitor {
    // 20 power-of-two buckets, thread-safe with lock-free atomic increments
    buckets: [AtomicU64; 20], 
}

impl LowOverheadMonitor {
    fn record(&self, latency_us: u64) {
        let idx = (64 - latency_us.leading_zeros() as usize).min(19);
        self.buckets[idx].fetch_add(1, Ordering::Relaxed);
    }
}
